test('newly read candidate indices remain hidden until final report verification',async()=>{
 const input=fixture();let verifications=0;input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose.includes('verify')){verifications++;return{verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'Fixture supports the literal claim.'}))};}if(purpose==='x-account-synthesize')throw Error('pause before final report');return{findings:[output()]};};
 await assert.rejects(analyzeXAccount(input),/pause before final report/);assert.equal(verifications,0,'draft indices do not receive paid per-draft verification');assert.equal(input.state.analysis.findings.length,1);assert.equal(input.state.analysis.findings[0]!.verified,false);
 assert.equal(projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['post-0'])}).findings.length,0);
});
test('a completed v4 reading job and old verified findings survive migration but cannot bypass global report creation',async()=>{
 const input=fixture();input.model=acceptModel();await analyzeXAccount(input);
 const batch=input.state.analysis.findings.find(f=>f.id.startsWith('batch:'))!;batch.verified=true;const old={...batch,id:'synthesis:legacy',statement:'旧阶段中，该账号自述制作了比较阅读笔记的工具。'};
 input.state.analysis.findings=[batch,old];input.state.analysis.completedBatches=input.state.analysis.completedBatches.filter(k=>!k.startsWith('report'));input.state.analysis.completedBatches.push('synthesis:v4:legacy');input.state.analysis.synthesisDone=true;
 const existing=[...input.state.analysis.completedBatches];let generations=0;input.model=async(request,signal)=>{if(request.purpose==='x-account-analyze'){generations++;throw Error('paid completed generation must not repeat');}return acceptModel()(request,signal);};await analyzeXAccount(input);
 assert.equal(generations,0);assert.ok(input.state.analysis.findings.find(f=>f.id===batch.id)!.verified);assert.ok(existing.every(k=>input.state.analysis.completedBatches.includes(k)));assert.ok(input.state.analysis.findings.some(f=>f.id.startsWith('report:')&&f.verified));assert.ok(input.state.analysis.completedBatches.some(k=>k.startsWith('report:v1:complete:')));
 const report=projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['post-0'])});assert.ok(report.findings.every(f=>f.id.startsWith('report:')));assert.equal(report.findings.some(f=>f.statement===old.statement),false);
});

test('invalid global planning ids receive bounded repairs and never become report facts',async()=>{
 for(const defect of ['invented','duplicate','missing']){const input=fixture(2,false);let plans=0;let writes=0;input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(data.organizationStage){plans++;if(defect==='missing')return{};const id=data.items[0].id;return{groups:[{section:'work',title:'Synthetic work',ids:defect==='invented'?['invented-id']:[id,id]}]};}if(purpose==='x-account-analyze')return{findings:data.materials.map((m:{sourceKey:string})=>output(m.sourceKey))};writes++;throw Error('invalid plan must not reach writing');};await analyzeXAccount(input);assert.equal(plans,3);assert.equal(writes,0);assert.equal(input.state.analysis.synthesisDone,false);assert.ok(!input.state.analysis.completedBatches.some(k=>k.startsWith('report-plan:v1:ready:')));assert.equal(projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(input.pages.map(p=>p.sourceKey))}).findings.length,0);}
});
test('a final report marker must match the latest ready plan and synthesis state',async()=>{
 const input=fixture();input.model=acceptModel();await analyzeXAccount(input);const report=()=>projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(['post-0'])});assert.ok(report().findings.some(f=>f.id.startsWith('report:')));
 input.state.analysis.synthesisDone=false;assert.equal(report().findings.length,0,'an incomplete global stage cannot publish earlier report text as finished');input.state.analysis.synthesisDone=true;
 input.state.analysis.completedBatches.push('report-plan:v1:ready:another-scope:another-plan');assert.equal(report().findings.length,0,'unrelated complete markers cannot authorize a different current plan');
});

test('global selection reads every candidate index and merges representatives across bounded index parts',async()=>{
 const input=fixture(95,false);const indexed=new Set<string>();const selectedByPart:string[]=[];let indexCalls=0,mergeCalls=0,finalCalls=0;
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(data.organizationStage==='index'){indexCalls++;selectedByPart[data.part]=data.items[0].id;for(const item of data.items)indexed.add(item.id);if(data.part===0)await new Promise<void>(resolve=>setImmediate(resolve));return{groups:[{section:'themes',title:'Reading tools over time',ids:[data.items[0].id]}]};}if(data.organizationStage==='merge'){mergeCalls++;return{groups:[{section:'themes',title:'One global reading-tool theme',ids:data.items.map((item:{id:string})=>item.id)}]};}if(purpose==='x-account-analyze')return{findings:data.materials.map((m:{sourceKey:string})=>output(m.sourceKey))};if(purpose.includes('verify'))return{verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'两篇原文支持有边界的概括。'}))};finalCalls++;assert.equal(data.findings.length,2);assert.deepEqual(data.findings.map((f:{id:string})=>f.id),selectedByPart,'out-of-order plan responses must preserve original part order');assert.ok(data.materials.every((m:{text:string})=>m.text.includes('I built the synthetic tool')));return{findings:[{section:'themes',statement:'该账号的两条帖子都自述制作了阅读笔记工具。',kind:'inference',evidence:data.findings.flatMap((f:{evidence:unknown[]})=>f.evidence)}]};};
 await analyzeXAccount(input);assert.equal(indexed.size,95);assert.equal(indexCalls,2);assert.equal(mergeCalls,1);assert.equal(finalCalls,1);assert.equal(input.state.analysis.findings.filter(f=>f.id.startsWith('batch:')).length,95);assert.ok(input.state.analysis.findings.filter(f=>f.id.startsWith('batch:')).every(f=>!f.verified));
 const report=projectXAccountReport({state:input.state,pages:input.pages,sources:sources(input),activeSourceKeys:new Set(input.pages.map(p=>p.sourceKey))});assert.equal(report.findings.length,1);assert.equal(report.findings[0]!.evidence.length,2);assert.equal(input.state.analysis.synthesisDone,true);
});
test('organization transport uncertainty and cancellation do not trigger plan repairs or publish candidates',async()=>{
 for(const scenario of ['transport','cancel']){const input=fixture(2,false);const controller=new AbortController();input.signal=controller.signal;let plans=0;input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(data.organizationStage){plans++;if(scenario==='transport')throw Error('unknown planning completion');controller.abort(Error('planning cancelled'));return{groups:[{section:'work',title:'Synthetic work',ids:data.items.map((item:{id:string})=>item.id)}]};}assert.equal(purpose,'x-account-analyze');return{findings:data.materials.map((m:{sourceKey:string})=>output(m.sourceKey))};};await assert.rejects(analyzeXAccount(input),scenario==='transport'?/unknown planning completion/:/planning cancelled/);assert.equal(plans,1);assert.ok(!input.state.analysis.completedBatches.some(k=>k.startsWith('report-plan:v1:ready:')));assert.equal(input.state.analysis.findings.filter(f=>f.verified).length,0);}
});
test('known plan defects can repair their ids but nonconvergent merges have a bounded stop',async()=>{
 const repaired=fixture(1,false);let attempts=0;repaired.model=async(request,signal)=>{const data=dataOf(request.prompt);if(data.organizationStage){attempts++;if(attempts===1)return{groups:[{section:'work',title:'Work',ids:['unknown']}]};assert.equal(data.protocolFeedback.code,'invalid_id');assert.equal(data.protocolAttempt,1);return{groups:[{section:'work',title:'Work',ids:[data.items[0].id]}]};}return acceptModel()(request,signal);};await analyzeXAccount(repaired);assert.equal(attempts,2);assert.equal(repaired.state.analysis.synthesisDone,true);
 const input=fixture(95,false);let mergeCalls=0;input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(data.organizationStage){if(data.organizationStage==='merge')mergeCalls++;return{groups:data.items.map((item:{id:string})=>({section:'work',title:'Separate synthetic fragment',ids:[item.id]}))};}assert.equal(purpose,'x-account-analyze');return{findings:data.materials.map((m:{sourceKey:string})=>output(m.sourceKey))};};await analyzeXAccount(input);assert.equal(mergeCalls,6);assert.equal(input.state.analysis.synthesisDone,false);assert.ok(input.state.gaps.some(g=>g.code==='analysis_batch_protocol_unverified'));assert.ok(!input.state.analysis.completedBatches.some(k=>k.startsWith('report-plan:v1:ready:')));
});

test('independent index planning parts run at most three concurrently before global merging',async()=>{
 const input=fixture(250,false);let active=0,peak=0,started=0;const releases:Array<()=>void>=[];
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(data.organizationStage==='index'){started++;active++;peak=Math.max(peak,active);if(started<=3)await new Promise<void>(resolve=>releases.push(resolve));active--;return{groups:[{section:'work',title:'Synthetic tools',ids:[data.items[0].id]}]};}if(data.organizationStage==='merge'){assert.equal(active,0);return{groups:[{section:'work',title:'One global tool theme',ids:data.items.map((item:{id:string})=>item.id)}]};}if(purpose.includes('verify'))return{verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'原文支持自述。'}))};return{findings:purpose==='x-account-analyze'?data.materials.map((m:{sourceKey:string})=>output(m.sourceKey)):[output(data.materials[0].sourceKey)]};};
 const operation=analyzeXAccount(input);await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(started,3);assert.equal(peak,3);for(const release of releases)release();await operation;assert.ok(started>3);assert.equal(peak,3);assert.equal(input.state.analysis.synthesisDone,true);
});

test('global organization waits for every material-reading job instead of buying a plan for an incomplete corpus',async()=>{
 const input=fixture(45,false);let downstreamCalls=0;
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(purpose==='x-account-analyze'){if(data.materials[0].sourceKey==='post-0')throw new DshProtocolRepairExhaustedError('invalid_decision_json',3);return{findings:[output(data.materials[0].sourceKey)]};}downstreamCalls++;if(data.organizationStage)return{groups:[{section:'work',title:'Work',ids:data.items.map((item:{id:string})=>item.id)}]};if(purpose.includes('verify'))return{verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'Synthetic support.'}))};return{findings:[output(data.materials[0].sourceKey)]};};await analyzeXAccount(input);assert.equal(downstreamCalls,0);assert.equal(input.state.analysis.completedBatches.filter(k=>k.startsWith('batch:')).length,2);assert.equal(input.state.analysis.synthesisDone,false);
});

test('near-linear global merges are refused after bounded repairs instead of buying many high-reasoning rounds',async()=>{
 const input=fixture(160,false);let mergeCalls=0;
 input.model=async({purpose,prompt})=>{const data=dataOf(prompt);if(data.organizationStage==='index')return{groups:data.items.map((item:{id:string})=>({section:'work',title:'A distinct synthetic fragment',ids:[item.id]}))};if(data.organizationStage==='merge'){mergeCalls++;if(data.requireConsolidation)return{groups:[{section:'work',title:'Two synthetic fragments',ids:data.items.slice(0,2).map((item:{id:string})=>item.id)},...data.items.slice(2).map((item:{id:string})=>({section:'work',title:'One unchanged fragment',ids:[item.id]}))]};return{groups:[{section:'work',title:'Synthetic global topic',ids:data.items.map((item:{id:string})=>item.id)}]};}if(purpose.includes('verify'))return{verdicts:data.findings.map((f:{id:string})=>({id:f.id,supported:true,reason:'Synthetic support.'}))};return{findings:purpose==='x-account-analyze'?data.materials.map((m:{sourceKey:string})=>output(m.sourceKey)):[output(data.materials[0].sourceKey)]};};
 await analyzeXAccount(input);assert.equal(mergeCalls,6,'two merge parts may each make only an initial attempt and two repairs');assert.equal(input.state.analysis.synthesisDone,false);assert.ok(input.state.gaps.some(g=>g.code==='analysis_batch_protocol_unverified'));assert.equal(input.state.analysis.findings.filter(f=>f.id.startsWith('batch:')).length,160,'cost bounds must not discard underlying candidate indices');assert.ok(!input.state.analysis.completedBatches.some(k=>k.startsWith('report-plan:v1:ready:')));
});
